package local.ttlab.gallery;

/** A query snapshot shared by count, paging and anchor lookup. */
final class MediaFilter {
    int channel,type,availability,watched,sort,shape,format,collection,archive;
    String query="";
    String webQuery;
    long albumId,tagId;boolean recent;
    boolean stacked;String stackKey="",stackMime="";long stackSize;
    static final String LAST_OPENED="CAST(COALESCE((SELECT r.opened_at FROM recent_media r WHERE r.channel=media.channel AND r.id=media.id AND r.revision=media.revision),0) AS INTEGER)";
    boolean duplicates;
    long from,until,minBytes,maxBytes,minSeconds,maxSeconds;
    MediaFilter(){}
    MediaFilter(int c,String q,int t,boolean offline,long f,long u,boolean d){channel=c;query=q;type=t;availability=offline?1:0;from=f;until=u;duplicates=d;}
    MediaFilter copy(){MediaFilter f=new MediaFilter(channel,query,type,availability==1,from,until,duplicates);f.webQuery=webQuery;f.availability=availability;f.watched=watched;f.sort=sort;f.shape=shape;f.format=format;f.collection=collection;f.archive=archive;f.minBytes=minBytes;f.maxBytes=maxBytes;f.minSeconds=minSeconds;f.maxSeconds=maxSeconds;f.albumId=albumId;f.tagId=tagId;f.recent=recent;f.stacked=stacked;f.stackKey=stackKey;f.stackMime=stackMime;f.stackSize=stackSize;return f;}
    void check(){if(webQuery!=null&&webQuery.length()>320)throw new IllegalArgumentException("Consulta web inválida");if(stackKey==null||stackMime==null||stackSize<0||stackSize>4L*1024*1024*1024||(!stackKey.isEmpty()&&(!stackKey.matches("[0-9a-f]{64}")||stackSize==0||!(stackMime.startsWith("video/")||stackMime.startsWith("image/"))))||(stackKey.isEmpty()&&(!stackMime.isEmpty()||stackSize!=0)))throw new IllegalArgumentException("Pila inválida");if(albumId<0||tagId<0||channel<0||query==null||type<0||type>2||availability<0||availability>2||watched<0||watched>2||sort<0||sort>6||shape<0||shape>3||format<0||format>7||collection<0||collection>3||archive<0||archive>2||from<0||until<0||(from>0&&until>0&&until<=from)||minBytes<0||maxBytes<0||(maxBytes>0&&minBytes>maxBytes)||minSeconds<0||maxSeconds<0||(maxSeconds>0&&minSeconds>maxSeconds))throw new IllegalArgumentException("Revisa los rangos y filtros");}
    String key(){return channel+":"+type+":"+availability+":"+watched+":"+sort+":"+shape+":"+format+":"+duplicates+":"+from+":"+until+":"+minBytes+":"+maxBytes+":"+minSeconds+":"+maxSeconds+":"+query.length()+":"+query+(webQuery==null?"":":web="+webQuery.length()+":"+webQuery)+(collection==0?"":":collection="+collection)+(archive==0?"":":archive="+archive)+(albumId==0?"":":album="+albumId)+(tagId==0?"":":tag="+tagId)+(recent?":recent":"")+(stacked?":stacked":"")+(stackKey.isEmpty()?"":":stack="+stackKey+":"+stackMime+":"+stackSize);}
    int active(){return (type>0?1:0)+(availability>0?1:0)+(watched>0?1:0)+(duplicates?1:0)+(from>0||until>0?1:0)+(minBytes>0||maxBytes>0?1:0)+(minSeconds>0||maxSeconds>0?1:0)+(shape>0?1:0)+(format>0?1:0)+(collection>0?1:0)+(archive>0?1:0)+(albumId>0?1:0)+(tagId>0?1:0)+(recent?1:0);}
    android.os.Bundle bundle(){check();android.os.Bundle b=new android.os.Bundle();b.putInt("channel",channel);b.putInt("type",type);b.putInt("availability",availability);b.putInt("watched",watched);b.putInt("sort",sort);b.putInt("shape",shape);b.putInt("format",format);b.putInt("collection",collection);b.putInt("archive",archive);b.putString("query",query);b.putString("web-query",webQuery);b.putBoolean("duplicates",duplicates);b.putLong("from",from);b.putLong("until",until);b.putLong("minBytes",minBytes);b.putLong("maxBytes",maxBytes);b.putLong("minSeconds",minSeconds);b.putLong("maxSeconds",maxSeconds);b.putLong("albumId",albumId);b.putLong("tagId",tagId);b.putBoolean("recent",recent);b.putBoolean("stacked",stacked);b.putString("stackKey",stackKey);b.putString("stackMime",stackMime);b.putLong("stackSize",stackSize);return b;}
    static MediaFilter from(android.os.Bundle b){MediaFilter f=new MediaFilter();if(b==null)return f;f.channel=b.getInt("channel");f.type=b.getInt("type");f.availability=b.getInt("availability");f.watched=b.getInt("watched");f.sort=b.getInt("sort");f.shape=b.getInt("shape");f.format=b.getInt("format");f.collection=b.getInt("collection");f.archive=b.getInt("archive");f.query=b.getString("query","");f.webQuery=b.getString("web-query");f.duplicates=b.getBoolean("duplicates");f.from=b.getLong("from");f.until=b.getLong("until");f.minBytes=b.getLong("minBytes");f.maxBytes=b.getLong("maxBytes");f.minSeconds=b.getLong("minSeconds");f.maxSeconds=b.getLong("maxSeconds");f.albumId=b.getLong("albumId");f.tagId=b.getLong("tagId");f.recent=b.getBoolean("recent");f.stacked=b.getBoolean("stacked");f.stackKey=b.getString("stackKey","");f.stackMime=b.getString("stackMime","");f.stackSize=b.getLong("stackSize");f.check();return f;}
    String mime(){return new String[]{"","image/jpeg","image/png","image/webp","image/gif","video/mp4","video/webm","video/x-matroska"}[format];}
    String primary(){return sort==6?LAST_OPENED:sort==2||sort==3?"size":sort==4?"duration":sort==5?"name COLLATE NOCASE":"date";}
    boolean ascending(){return sort==1||sort==3||sort==5;}
    String order(){String p=primary();return p+(ascending()?" ASC":" DESC")+(p.equals("date")?"":",date DESC")+(sort==1?",id ASC":",id DESC")+",channel ASC";}
}
